CREATE OR REPLACE PROCEDURE dbp_macro.m_ups_ts_wbs_refmarkt(IN P_MANDANT_ID FLOAT64, IN P_WUP_ID FLOAT64, IN P_NB_ID FLOAT64, IN P_WUP_CONCAT_REF STRING, IN P_REF_FAKTOR_FALLBACK FLOAT64, IN P_WUP_VZ_CONCAT_FALLBACK STRING, IN P_FIXAMOUNT_SHARE_ALG_500 FLOAT64, IN P_FIXAMOUNT_SHARE_ALG_120 FLOAT64, IN P_ESTIMATION_FG FLOAT64, IN P_ADJUSTMENT_FG FLOAT64, OUT out_param STRING)
BEGIN
DECLARE dummy_2 FLOAT64;
BEGIN
BEGIN TRANSACTION;
-- Wenn Eintrag vorhanden loeschen 
DELETE FROM dbp_msi_data.ts_wbs_refmarkt_2
WHERE mandant_id = P_MANDANT_ID AND wup_id = P_WUP_ID AND nb_id = P_NB_ID;
-- Eintrag einfügen 
INSERT INTO dbp_msi_data.ts_wbs_refmarkt_2 (mandant_id, wup_id, nb_id, wup_id_ref, nb_id_ref, ref_faktor_fallback, mandant_id_vz_fallback, wup_id_vz_fallback, nb_id_vz_fallback, fixamount_share_alg_500, fixamount_share_alg_120, estimation_fg, adjustment_id)
(SELECT CAST(P_MANDANT_ID AS INTEGER) AS mandant_id, CAST(P_WUP_ID AS INTEGER) AS wup_id, CAST(P_NB_ID AS INTEGER) AS nb_id, CAST(ROUND(CAST(CASE WHEN P_WUP_CONCAT_REF IS NOT NULL THEN IFNULL(SPLIT(P_WUP_CONCAT_REF, ':')[SAFE_OFFSET(0)], '') ELSE NULL END AS BIGNUMERIC), 0) AS INTEGER) AS wup_id_ref, CAST(ROUND(CAST(CASE WHEN P_WUP_CONCAT_REF IS NOT NULL THEN IFNULL(SPLIT(P_WUP_CONCAT_REF, ':')[SAFE_OFFSET(1)], '') ELSE NULL END AS BIGNUMERIC), 0) AS INTEGER) AS nb_id_ref, ROUND(CAST(P_REF_FAKTOR_FALLBACK AS NUMERIC), 2) AS ref_faktor_fallback, CAST(ROUND(CAST(CASE WHEN P_WUP_VZ_CONCAT_FALLBACK IS NOT NULL THEN IFNULL(SPLIT(P_WUP_VZ_CONCAT_FALLBACK, ':')[SAFE_OFFSET(0)], '') ELSE NULL END AS BIGNUMERIC), 0) AS INTEGER) AS mandant_id_vz_fallback, CAST(ROUND(CAST(CASE WHEN P_WUP_VZ_CONCAT_FALLBACK IS NOT NULL THEN IFNULL(SPLIT(P_WUP_VZ_CONCAT_FALLBACK, ':')[SAFE_OFFSET(1)], '') ELSE NULL END AS BIGNUMERIC), 0) AS INTEGER) AS wup_id_vz_fallback, CAST(ROUND(CAST(CASE WHEN P_WUP_VZ_CONCAT_FALLBACK IS NOT NULL THEN IFNULL(SPLIT(P_WUP_VZ_CONCAT_FALLBACK, ':')[SAFE_OFFSET(2)], '') ELSE NULL END AS BIGNUMERIC), 0) AS INTEGER) AS nb_id_vz_fallback, ROUND(CAST(P_FIXAMOUNT_SHARE_ALG_500 AS NUMERIC), 3) AS fixamount_share_alg_500, ROUND(CAST(P_FIXAMOUNT_SHARE_ALG_120 AS NUMERIC), 3) AS fixamount_share_alg_120, CAST(P_ESTIMATION_FG AS INTEGER) AS estimation_fg, CAST(P_ADJUSTMENT_FG AS INTEGER) AS adjustment_id);
COMMIT TRANSACTION;
SET out_param  =  'Referenzmarkt gespeichert.';
SELECT out_param;
RETURN;
END;
END;



